go_code = r'''
package main

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"fmt"
)

const charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

func polymod(values []int) int {
	GEN := []int{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := 1
	for _, v := range values {
		b := chk >> 25
		chk = ((chk & 0x1ffffff) << 5) ^ v
		for i := 0; i < 5; i++ {
			if (b>>i)&1 == 1 {
				chk ^= GEN[i]
			}
		}
	}
	return chk
}
func hrpExpand(hrp string) []int {
	var ret []int
	for _, c := range hrp {
		ret = append(ret, int(c)>>5)
	}
	ret = append(ret, 0)
	for _, c := range hrp {
		ret = append(ret, int(c)&31)
	}
	return ret
}
func createChecksum(hrp string, data []int) []int {
	vals := append(hrpExpand(hrp), data...)
	vals = append(vals, 0,0,0,0,0,0)
	polymod := polymod(vals) ^ 1
	var ret []int
	for i:=0;i<6;i++ {
		ret = append(ret, (polymod >> (5*(5-i))) & 31)
	}
	return ret
}
func convertbits(data []byte, frombits, tobits int, pad bool) []int {
	var ret []int
	acc:=0; bits:=0; maxv:=(1<<tobits)-1
	for _, v := range data {
		acc = (acc<<frombits)|int(v)
		bits+=frombits
		for bits>=tobits {
			bits-=tobits
			ret=append(ret, (acc>>bits)&maxv)
		}
	}
	if pad && bits>0 {
		ret=append(ret, (acc<<(tobits-bits))&maxv)
	}
	return ret
}
func encode(hrp string, data []byte) string {
	data5 := convertbits(data, 8,5,true)
	check := createChecksum(hrp, data5)
	combined := append(data5, check...)
	s:=hrp+"1"
	for _, d := range combined {
		s+=string(charset[d])
	}
	return s
}
func main() {
	k, _ := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	comp := elliptic.MarshalCompressed(elliptic.P256(), k.X, k.Y)
	enc := encode("age1tag", comp)
	fmt.Println(enc)
	fmt.Printf("%x\n", comp)
	// also uncompressed for tagpq? need mlkem part too, skip for now
	// print priv?
	fmt.Printf("%x\n", k.D.Bytes())
}
'''
